#include <stdio.h>
int adj[4][4] = {{0,1,0,0},{1,0,1,0},{0,1,0,1},{0,0,1,0}};
int dist[4] = {-1,-1,-1,-1};
int main(void) {
    int q[4], f = 0, r = 0; q[r++] = 0; dist[0] = 0;
    while (f < r) {
        int u = q[f++];
        for (int v = 0; v < 4; v++)
            if (adj[u][v] && dist[v] == -1) { dist[v] = dist[u] + 1; q[r++] = v; }
    }
    printf("%d %d %d %d\n", dist[0], dist[1], dist[2], dist[3]);
    return 0;
}
